@js:
const createItem = (t, u, p) => ({ title: t, url: u || "", style: { layout_flexGrow: 1, layout_flexBasisPercent: p } });
const dataList = [createItem("排行榜", "", 1)];

// 提取排行榜公共前缀
const rankPrefix = "/top/rankings/";
[
  ["日点击榜", "dayvisit"],
  ["周点击榜", "weekvisit"],
  ["月点击榜", "monthvisit"],
  ["总点击榜", "allvisit"],
  ["日推荐榜", "dayvote"],
  ["周推荐榜", "weekvote"],
  ["月推荐榜", "monthvote"],
  ["总推荐榜", "allvote"],
  ["总收藏榜", "goodnum"],
  ["字数排行", "size"],
  ["最新入库", "postdate"],
  ["最近更新", "lastupdate"]
].forEach(([t, path]) => dataList.push(createItem(t, `${rankPrefix}${path}/{{page}}.shtml`, 0.25)));

dataList.push(createItem("书库", "", 1));

// 提取书库公共前缀
const bookPrefix = "/typeinfo/type-";
[
  ["玄幻魔法", 1],
  ["武侠修真", 2],
  ["都市言情", 3],
  ["历史军事", 4],
  ["网游竞技", 5],
  ["科幻小说", 6],
  ["恐怖灵异", 7],
  ["其他小说", 8]
].forEach(([t, type]) => dataList.push(createItem(t, `${bookPrefix}${type}/{{page}}-pg.shtml`, 0.25)));
// 单独处理完结小说（路径无规律）
dataList.push(createItem("完结小说", "/completepage/read-1-final.shtml", 0.5));

JSON.stringify(dataList, null, 2);

